import click
from click.testing import CliRunner

def parse_port(value):
    v = int(value)
    if not 1 <= v <= 65535:
        raise ValueError("port must be between 1 and 65535")
    return v

@click.command()
@click.option("--port", type=parse_port)
def cli(port): pass

r = CliRunner().invoke(cli, ["--port", "70000"], catch_exceptions=False)
print(repr(r.output))
assert "port must be between 1 and 65535" in r.output

# ValueError with no message -> falls back to offending value
def bad(value):
    raise ValueError

@click.command()
@click.option("--x", type=bad)
def cli2(x): pass
r2 = CliRunner().invoke(cli2, ["--x", "abc"], catch_exceptions=False)
print(repr(r2.output))
assert "abc" in r2.output

# bytes value with no message, str() raises -> decode utf-8 with replacement
def badbytes(value):
    raise ValueError

@click.command()
@click.option("--y", type=badbytes)
def cli3(y): pass
r3 = CliRunner().invoke(cli3, ["--y", b"\xff\xfe"], catch_exceptions=False)
print(repr(r3.output))

# good value still works
r4 = CliRunner().invoke(cli, ["--port", "8080"])
assert r4.exit_code == 0, r4.output
print("ok")
